package cl.uss.ca.external.pure.model;

public class JournalIssnData {
    private Long pureId;
    private String issn;

    public Long getPureId() {
        return pureId;
    }

    public void setPureId(Long pureId) {
        this.pureId = pureId;
    }

    public String getIssn() {
        return issn;
    }

    public void setIssn(String issn) {
        this.issn = issn;
    }
}
